// Pull GA4 events from Windsor's CONNECTOR API rather than a destination task.
//
// Windsor's plan caps *destination tasks* (their push mechanism) at 5, and all five are used:
// GA4 totals/source/geo + Google Ads + Meta. The connector URL is just an HTTP endpoint
// though, so a fourth GA4 grain can be pulled here instead of pushed there. No upgrade
// needed, and we control the transform.
//
// Why a fourth grain is unavoidable: GA4 applies thresholding per query, so a breakdown never
// sums to the total. Verified -- source sessions 5,107/3,757 vs true totals 5,104/3,575 for
// Aug/Sep. One task per grain is a GA4 constraint, not a Windsor one.
const API_KEY = 'WINDSOR_API_KEY';
const DAYS = 30;

// All fields are [Event]-scoped, so GA4 accepts the combination. Pairing scopes incorrectly
// is what got `source_medium` rejected outright -- see migration 029.
const FIELDS = 'date,event_name,is_conversion_event,event_count,conversions,event_value';
const url = `https://connectors.windsor.ai/googleanalytics4?date_preset=last_${DAYS}d`
          + `&fields=${FIELDS}&api_key=${API_KEY}`;

let payload;
let lastErr = null;
for (let attempt = 1; attempt <= 4; attempt++) {
  try {
    payload = await this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: 120000 });
    break;
  } catch (e) {
    lastErr = e;
    if (attempt < 4) await new Promise((r) => setTimeout(r, 2000 * attempt));
  }
}
if (!payload) throw new Error(`Windsor connector failed after 4 tries: ${lastErr && lastErr.message}`);

// Windsor wraps rows in {data: [...]} on some endpoints and returns a bare array on others.
const rows = Array.isArray(payload) ? payload : (payload.data || []);
if (!Array.isArray(rows)) throw new Error(`unexpected response shape: ${JSON.stringify(payload).slice(0, 200)}`);

// Empty is NOT normal here -- GA4 always emits events. Fail loudly rather than write nothing
// and look healthy, which is the failure mode that hid a five-week outage.
if (rows.length === 0) throw new Error('Windsor returned 0 event rows -- refusing to treat as success');

const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(v);
  return isNaN(n) ? null : n;
};

// De-duplicate on the primary key before POSTing. A repeated key inside one batch raises
// "ON CONFLICT DO UPDATE command cannot affect row a second time" and fails the WHOLE batch.
const byKey = new Map();
for (const r of rows) {
  if (!r || !r.date || !r.event_name) continue;
  byKey.set(`${r.date}|${r.event_name}`, {
    date: String(r.date).slice(0, 10),
    event_name: String(r.event_name),
    is_conversion_event: r.is_conversion_event === null || r.is_conversion_event === undefined
      ? null : String(r.is_conversion_event),
    event_count: num(r.event_count),
    conversions: num(r.conversions),
    event_value: num(r.event_value),
    synced_at: new Date().toISOString(),
  });
}
const out = Array.from(byKey.values());
if (out.length === 0) throw new Error('all rows lacked date/event_name -- nothing usable');
return out.map((json) => ({ json }));
